package main

import (
	"bytes"
	"errors"
	"fmt"
	"go/format"
	"go/types"
	"os"
	"path/filepath"
	"strconv"
	"text/template"
)

// imports names the packages the generated file refers to: each path gets
// one name, the package's own unless that is taken by another import, a
// declaration of the package or a generated name.
type imports struct {
	self     *types.Package
	byPath   map[string]string
	pkgNames map[string]string
	names    map[string]string
}

func newImports(self *types.Package) *imports {
	im := &imports{self: self, byPath: map[string]string{}, pkgNames: map[string]string{}, names: map[string]string{}}
	im.name(ormImport, "orm")
	return im
}

func (im *imports) reserve(names ...string) {
	for _, n := range names {
		im.names[n] = ""
	}
}

func (im *imports) name(path, want string) string {
	if n, ok := im.byPath[path]; ok {
		return n
	}
	n := want
	for i := 2; im.taken(n); i++ {
		n = want + strconv.Itoa(i)
	}
	im.byPath[path], im.pkgNames[path], im.names[n] = n, want, path
	return n
}

func (im *imports) taken(n string) bool {
	_, ok := im.names[n]
	return ok || im.self.Scope().Lookup(n) != nil
}

func (im *imports) orm() string { return im.byPath[ormImport] }

func (im *imports) typeString(t types.Type) string {
	return types.TypeString(t, func(p *types.Package) string {
		if p == im.self {
			return ""
		}
		return im.name(p.Path(), p.Name())
	})
}

// specs lists the imports the generated file needs, by path, with the
// name written only where it differs from the package's own.
func (im *imports) specs() map[string]string {
	out := map[string]string{}
	for path, n := range im.byPath {
		if n == im.pkgNames[path] {
			n = ""
		}
		out[path] = n
	}
	return out
}

var tmpl = template.Must(template.New("").Parse(`// Code generated by ormgen. DO NOT EDIT.

package {{.Pkg}}

import (
{{- range $path, $name := .Imports}}
	{{$name}} "{{$path}}"
{{- end}}
)
{{$orm := .Orm}}
{{- range .Models}}{{$m := .}}
var {{.Var}} = &{{$orm}}.Table[{{.Struct}}, {{.KeyType}}]{
	Name:       "{{.Table}}",
{{- if .Connection}}
	Connection: "{{.Connection}}",
{{- end}}
{{- if .Key}}
	PrimaryKey: "{{.Key}}",
	KeyType:    {{$orm}}.{{.KeyGen}},
{{- end}}
{{- if .CreatedAt}}
	CreatedAt:  "{{.CreatedAt}}",
{{- end}}
{{- if .UpdatedAt}}
	UpdatedAt:  "{{.UpdatedAt}}",
{{- end}}
{{- if .DeletedAt}}
	DeletedAt:  "{{.DeletedAt}}",
{{- end}}
{{- if .Morph}}
	MorphAlias: "{{.Morph}}",
{{- end}}
{{- if .TimePrecision}}
	TimePrecision: {{.TimePrecision}},
{{- end}}
{{- $nz := false}}{{range .Fields}}{{if .NullZero}}{{$nz = true}}{{end}}{{end}}
{{- if $nz}}
	NullZero: []string{ {{- $f1 := true}}{{range .Fields}}{{if .NullZero}}{{if not $f1}}, {{end}}"{{.Column}}"{{$f1 = false}}{{end}}{{end -}} },
{{- end}}
	Columns: []string{ {{- $first := true}}{{range .Fields}}{{if not .Virtual}}{{if not $first}}, {{end}}"{{.Column}}"{{$first = false}}{{end}}{{end -}} },
	Ptr: func(m *{{.Struct}}, column string) any {
		switch column {
{{- range .Fields}}
		case "{{.Column}}":
			return &m.{{.Path}}
{{- end}}
		}
		return nil
	},
	State: func(m *{{.Struct}}) *{{$orm}}.Model { return &m.{{.ModelPath}} },
}

// {{.SchemaType}} describes the {{.Table}} table for {{.Struct}}.
type {{.SchemaType}} struct {
	*{{$orm}}.Table[{{.Struct}}, {{.KeyType}}]
{{- range .Fields}}
	// {{.Name}} is {{if .Virtual}}virtual, not stored: selected extras only{{else}}the {{$m.Table}}.{{.Column}} column{{end}} of {{$m.Struct}} ({{.Type}}).
	{{.Name}} {{$orm}}.Column[{{$m.Struct}}, {{$m.KeyType}}, {{.Type}}]
{{- end}}
}

// {{.Schema}} is the entry point for the {{.Table}} table ({{.Struct}}):
// {{.Schema}}.Query(), {{.Schema}}.Find(id), {{.Schema}}.Where({{.Schema}}.{{(index .Fields 0).Name}}...) ...
var {{.Schema}} = {{.SchemaType}}{
	Table: {{.Var}},
{{- range .Fields}}
	{{.Name}}: {{$orm}}.{{if .Virtual}}NewVirtualColumn{{else}}NewColumn{{end}}({{$m.Var}}, "{{.Column}}", func(m *{{$m.Struct}}) *{{.Type}} { return &m.{{.Path}} }),
{{- end}}
}

// {{.Query}} is a query over {{.Table}}, for scopes:
// func(q {{.Query}}) {{.Query}}.
type {{.Query}} = {{$orm}}.Query[{{.Struct}}, {{.KeyType}}]
{{end}}`))

func render(l loaded, ms []model, im *imports) ([]byte, error) {
	var buf bytes.Buffer
	data := map[string]any{"Pkg": l.pkg.Name(), "Models": ms, "Imports": im.specs(), "Orm": im.orm()}
	if err := tmpl.Execute(&buf, data); err != nil {
		return nil, fmt.Errorf("ormgen: rendering: %w", err)
	}
	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("ormgen: formatting generated code: %w\n%s", err, buf.Bytes())
	}
	return src, nil
}

// writeAtomic replaces path with src through a temporary file in the same
// directory, so a failed run never leaves a half-written source behind.
func writeAtomic(path string, src []byte) error {
	tmp, err := os.CreateTemp(filepath.Dir(path), ".ormgen-*.go")
	if err != nil {
		return fmt.Errorf("ormgen: writing %s: %w", path, err)
	}
	_, err = tmp.Write(src)
	if err == nil {
		err = tmp.Chmod(0o644)
	}
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}
	if err == nil {
		err = os.Rename(tmp.Name(), path)
	}
	if err != nil {
		return errors.Join(fmt.Errorf("ormgen: writing %s: %w", path, err), os.Remove(tmp.Name()))
	}
	return nil
}
